#!/usr/bin/env node
/**
 * Starts an MCP server from npm with npx, the same way on Windows and macOS.
 * (On Windows, agent tools cannot start `npx` directly without a `cmd /c`
 * wrapper, which in turn breaks on macOS. `node` works everywhere.)
 *
 *   node scripts/mcp-run.mjs <npm-package> [args...]
 *
 * Used by the MCP configs generated by scripts/agents-sync.mjs.
 */
import { spawn } from "node:child_process"

const args = process.argv.slice(2)
if (args.length === 0) {
  console.error("usage: node scripts/mcp-run.mjs <npm-package> [args...]")
  process.exit(1)
}

const isWindows = process.platform === "win32"
const child = spawn(isWindows ? "npx.cmd" : "npx", ["-y", ...args], {
  stdio: "inherit",
  shell: isWindows,
})
child.on("error", (error) => {
  console.error(`Could not start ${args[0]}: ${error.message}`)
  process.exit(1)
})
child.on("exit", (code, signal) => process.exit(code ?? (signal ? 1 : 0)))
